import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"解","description":"高島易斷 - 解","frontmatter":{"title":"解","description":"高島易斷 - 解"},"headers":[],"relativePath":"classics/takashima/040.md","filePath":"classics/takashima/040.md"}'),i={name:"classics/takashima/040.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><h2 id="解-1" tabindex="-1">解 <a class="header-anchor" href="#解-1" aria-label="Permalink to “解”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>解：利西南。無攸往，其來複吉。有攸往，夙吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>“解，緩也。”《坎》位北，《震》位東，自北轉東，而南，而西，是行也，故曰“利西南”。《解》即所以解蹇，反東北而東南，倒《震》《坎》。《解》之西南，即《蹇》之西南也，故其利同。“無攸往”者，謂蹇解而難已平，無難則無所往，緩以養之，以俟來複，是以“來複吉”也。“有攸往”者，謂蹇解而難猶在，有難則必有往，急，不懈夙興，是以“夙吉”也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>雷雨作，解，君子以赦過宥罪。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>按：十二消息考，《坎》為十二月至正月之卦，《坎》五六兩爻，值雨水驚蟄；《震》為二月至四月之卦，《震》初爻，值雷乃發聲，三爻值穀雨。《解》為二月公卦，《象》曰“雷雨作”，蓋因其時而取象焉。《坎》為罪，為災，故有過有罪；《震》為緩，為生，故用“赦”用“宥”。君子法之，號令如雷之《震》，天下無不聳動，恩澤如雨之降，天下無不喜悅。夫使幽閉久系之人，一旦得“赦過宥罪”，弛其禁錮，脫其桎枯，如出陷阱而復見天日，則其憂悶鬱結之氣，無不解散。是君子與民更新，以之解萬民之難也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：災難解脫，大有奮發振作之象。</p><p>○　問戰徵：威武一振，有大寇翦滅，小寇服從之象。</p><p>○　問功名：有聲震百里，澤被群生之兆。</p><p>○　問營商：得時得令，“雷雨之動滿盈”，大利。</p><p>○　問婚姻：《震》雷《坎》雨，陰陽交濟，生育暢茂，吉。</p><p>○　問家宅：天盤有動，地盤有難，宜祈禱解免</p><p>○　問行人：一時可歸，防小有災難，無咎。</p><p>○　問訟事：幸得寬宥無罪。</p><p>○　問六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《解》之始，大難初平，不求有功，只求無咎。初與四應，賴應之力，得解其險，故曰“無咎”。《象傳》所謂“剛”者，指四，“柔”者指初，“際”者，謂初與四相應，陰陽相交，其義自可無咎也。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：困難初解，安時守分，自得無咎。</p><p>○　問戰徵：乍脫重圍，宜自蓄銳養精，不可妄動，得保無咎</p><p>○　問營商：不致耗失，亦為幸矣。</p><p>○　問功名：目下只可守舊而已。</p><p>○　問家宅：平安無害。</p><p>○　問訟事：宜和。</p><p>○　問婚姻：平平。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治二十四年三月，為鄭永寧與清國公使館內通書函，一時議論紛起，真偽莫辨，製紙分社長陽其二氏來書，請佔一卦，以判虛實。筮得《解》之《歸妹》。</p><p>斷曰：《解》者，釋也，堅冰得暖而解散之象也。初爻曰“無咎”，《易》之爻辭，單言“無咎”者，惟此一爻，是天張其口，以證鄭氏之無罪也。且《解》者，謂解脫罪過，初爻之陰屬鄭氏，四爻之陽屬清國公使，陰陽相應，知情分頗厚，然於國家大義，一無關害。《象傳》曰“君子赦過宥罪”，料日後審官，亦必原情赦宥，斷不以無稽文字，為之追究也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“田”者，獵也。上互《坎》，《坎》為狐，下互《離》，《離》為黃矢。狐陰獸，善惑人，故譬言妄邪小人，蠱惑君聰。“三”者，言數之多也。“黃”者，正色；“矢”者，直也。二爻以陽居陰，剛柔得中，上與六五，陰陽相應，為能輔佐大君，進賢黜邪，用以匡濟時艱者也。蓋欲解難，當先驅狐，故取《離》之矢，就《坤》之田，獲《坎》之群狐而盡殲之，斯內治肅靖，於以濟險出危，納一世於中道，其在此矣，是以九二“貞吉”也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：去邪歸正，自得安吉。</p><p>○　問戰徵：“田”者獵獸，猶戰之獵敵也。獲狐者，猶獲敵之渠魁也。得矢者，猶得敵之兵器也。故“貞吉”。</p><p>○　問營商：“田”者在獵獸，商者在獵利，“三”者多數，“黃”者黃金。必獲厚利，吉。</p><p>○　問功名：曰“獲”，曰“得”，功名可望，吉。</p><p>○　問家宅：此宅防有狐祟，須獵獲之，乃吉。</p><p>○　問婚姻：此必先有小妾，而後納正室也。黃者正色，為正配，吉。</p><p>○　問疾病：防是狐媚邪病，宜張弧矢以驅之，吉。</p><p>○　問六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某商人佔氣運，筮得《解》之《豫》。</p><p>斷曰：獲狐得矢，知獵財獵名，無往不利。足下災難既解，所求必得，正是好運發動，有雷雨得時之象。“黃”為正色，“矢”為直，又知足下品行正直，不惑於狐媚，是能以正治邪，故“貞吉”。</p><p>明治二十五年，餘患鼻痔，呼吸不通，談話亦困，頗覺苦之。聞金杉某，留學獨逸，專修鼻科，歸朝設院受診，餘欲求治，筮得《解》之《豫》。</p><p>斷曰：內卦水險，外卦雷動，動而免險之象，故不宜坐視，宜速治療，解去疾病之難也。佔得第二爻，為《坎》之主，動而變《豫》，有預治之象。“田”為狩獵，“狐”為怪物，“黃矢”者，射其怪物之矢。今鼻中之疣，身之怪物也，“三”者，為數之多；“黃矢”者；想為醫治之器也，爻可備觀，其象則吉。餘於是向金杉氏乞治，金杉氏一診，許為易治，先用麻藥，通電氣於銅線，系掛於疣上，遂得截斷其疣。疣數不一，悉皆截去，病苦頓解。醫術之妙，實可驚喜，而《易》機之先示，悉合其狀，更可驚歎。鳴呼！《易》者以森羅萬象之事物，照徹於三百八十四爻之中，一一發露其靈機，以垂教於天下後世，聖人之所以為聖人也！</p><p>相州橫須賀建築炮臺，又有造船大工場，年年埋築海面，因採土炭岩石，向歸大倉久米馬擔保，其岩石用船運至海岸築處，並用小輪船為引，以取快疾。大倉組遂自造運船；免受僱船勒索等弊，指揮得當，獨佔利益。在官寮察知一人專擔，難免弊竇，欲命高島嘉兵衛分承其役，於是大倉組忌之，隱使船伕等百般妨礙，且故意寬支賃金，每日所損，不下七八百元，兩傢俱受其困。餘乃請佔一卦，筮得《解》之《豫》。</p><p>斷曰：《彖傳》謂“解，險以動，動而免乎險”，明言一動乃可出險。就佔所言，爻以二五為紛爭之主，今得二爻，二在內卦，屬高島氏，五在外卦，屬大倉氏，二之負擔，為四所妨，遂致互生吱唔，互受虧折。爻辭曰“三狐”，謂彼有三人，狡猾妨事；“黃矢”，謂我有一人，正直當事。以矢射狐，而狐退矣。四爻曰“朋至斯孚”，“朋”者，謂居間而講和之友，“孚者，謂二五兩主，得以感孚而罷爭也。五本君子，始為小人所狐惑，故曰“君子有解，小人退也”。乃依此佔，使橫山孫一郎傳高島氏之意於大倉氏，事遂平和。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“負”者，竊負，“乘”者，乘肥，“負且乘”，是竊盜而公卿也，故“可醜”。“致寇至”者，《坎》為寇。六三處《坎》體，本寇也，寇以遭時竊位，得以策肥乘堅，為寇者見之，曰彼亦寇也，今居然“負且乘”矣，是可取而代之也。此謂以寇名寇。當此險難甫解，而使寇者濫居高位，豈非用人者之咎乎？故曰“自我致戎”，咎復何辭？“吝”，即醜也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：運非不佳，但因素行不端，為人鄙笑。</p><p>○　問戰徵：戰隙自我而開，以致群盜紛起，一時難平。</p><p>○　問營商：防有盜劫之患。</p><p>○　問功名：沐猴而冠，其能久乎？</p><p>○　問家宅：門戶不自謹慎，或用人不當，致招竊盜。</p><p>○　問婚姻：兩姓均非端正之家，是富而不仁者也，“可醜”</p><p>○　問訟事：兩造理皆不直。</p><p>○　問行人：滿載而歸，但來路不正。</p><p>○　問失物：已被竊負盜去，不得。</p><p>○　問六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>某人來，請佔某區長品行，筮得《解》之《恆》。</p><p>斷曰：負為肩負，小人之役也，乘為乘車，君子之分也，“負且乘”，是以小人而竊居君子之分也。寇者見之曰：是亦寇也，彼以寇顯，我豈獨不可顯乎？故曰以寇招寇，醜有由來也。觀此爻辭，則知某氏得為區長，亦寇取而得之，必有寇伺其後者也，何能久居其任乎？未幾果罷職。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四居《震》之始，《震》為足，“拇”，足大指也。四為《解》之主，《解》即解其蹇也。蹇為足疾，疾在一拇，不足以為《蹇》，解在一拇，亦不成其為《解》。四不當位，故不能全解其蹇，第見“解爾拇”，“拇”，即指四而汝也，故曰“爾拇”。《解》之四，即從《蹇》五來，《蹇》五曰“朋來”，故《解》四曰“朋至”。四亦自知其不能解蹇，惟望“朋至”，得以相助為理。將由拇以及心，斯心心相感，而《蹇》得全《解》矣。《坎》為孚，故曰“孚”。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：行年已當強仕，但行運不當，全在因人成事</p><p>○　問戰徵：防炮彈傷足，幸救兵得力，可以解圍。</p><p>○　問營商：所獲甚微，惟眾心交孚，一二年後，可望厚利。</p><p>○　問功名：拇為足指，卑下已極，至五爻日“君子維有解”必待下科，可望登榜。</p><p>○　問家宅：此宅地低下，不得其當，只可作行棧店屋。</p><p>○　問婚姻：得有力媒人說合，方可成事。</p><p>○　問訟事：有朋友出，交相解勸，得可息訟。</p><p>○　問六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>群馬縣高崎市某甲書來，曰僕近鄰有乙某者，一子罹病危篤，禱於榛名神社，不日而愈，乙某深喜之，偕子謁謝神社。一日乙某以遺金盡付其子曰：餘居處，恐遭殺害，突然而行，同子即出而追尋，不知去向，舉家不堪悲嘆。請勞一佔，以卜吉兇。餘時適罹疾，因使門弟筮之，得《解》之《師》。</p><p>餘見此佔，問門弟將何以斷之？門弟答曰：乙某不入山，亦不投水，在東方朋友之家而已。《彖傳》曰，“解，險以動，動而免乎險”，乙某自言，恐遭殺害而逃去，是因險而動也；既得逃避，是“動而免乎險”也。爻辭曰“解而拇，朋至斯孚”，“拇”為足大指，父子一體，子在下，是足指也。遺金而別，解拇者也；“朋至斯孚”，是明言在朋友之家也。“孚”者，得朋友一言而心感也。餘喜判語適當，遂書其斷語而函告之。後面會某甲，詢及此佔，曰乙某蹤跡，適如貴佔云云。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>此“君子”，即《大象》所云“赦過宥罪”之“君子”也。五居尊位，與二相應，二既能得其中道，以祛群邪，許其更新，五即因之，原情赦宥，不復窮究，是以不解為《解》者也，小人遂感而有孚，是以吉也。《象傳》曰，“君子有解，小人退也”，謂君子不必力去小人，小人自心服君子，不敢與君子同居。自古奸邪害政，皆由君子不能感化小人，小人是以不信服君子，以致傾軋。覆轍相尋，皆未明六五“有解”之旨也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：正運亨通，群邪悉退。</p><p>○　問戰徵：不戮一人，不加一矢，外夷來服。</p><p>○　問功名：利君子，不利小人。</p><p>○　問營商：不勞苦計營謀，自然獲利。</p><p>○　問家宅：此宅福曜照臨，邪魔遠避。</p><p>○　問婚姻：吉。</p><p>○　問行人：即歸。</p><p>○　問疾病：外邪解散，正氣來複，吉。</p><p>○　問訟事：理直者勝，理曲者服，即可罷訟。</p><p>○　問六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人橫山孫一郎氏來，曰：近見新聞紙所揭福地氏下獄，想此老衰之身，際此炎暑，其困難不言可知。推其所由，為得金草文，在草文得金，與受賄營私者，固有別焉。公冶縲紲，孔子特以非罪明之，予將為福地氏籌一解救之方，請煩一佔。筮得《解》之《困》。</p><p>斷曰：《解》者，解散也。佔得第五爻，為《解》之主，爻辭曰“君子維有解”，且系以“吉”，稱曰“君子”，知罪非其罪，不以罪而賤其人也。曰“維有解，”知不解而解，不待救而自然脫罪也。曰“有孚於小人”，在被起事之小人，亦知陷害君子，於心不忍，自願認罪而退也。福地氏暫受其厄，自得安吉。餘因面東京裁判檢事，具語此易，不日而福地氏出獄。閱後有相知永井泰次郎氏，以訟事嫌疑，牽連被引，伊妻來請一佔，又得此爻，遂即將此判詞告之。永井氏亦果以無罪放免。其事同，其爻同，其應驗亦果相同，故附記之。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>《震》為諸侯，故稱“公”；《坎》為弧，為弓，故曰“射”。卦體上互《離》，《離》為飛鳥，故有隼象；四動而成《坤》，《坤》為城墉，象城墉之上。上爻居《解》之極，自初至五，凡用剛，用柔，用猛，用寬，所以解除內難，亦既備矣，至上猶有飛翔在外，如鷙鳥之強悍者，五乃命六曰：公其乘《坤》之墉，張《離》之弧，抽一矢而射之，獲其魁首，無不利也，以解悖也。《坎》為悖，謂滅此悖逆之徒，斯內患外寇，悉皆掃平矣。前諸爻，即《彖》所云“其來複吉”；上爻乃《彖》雲“有攸往，夙吉”是也。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：運途吉順，出外或遇小寇，宜急防之。</p><p>○　問戰徵：防有敵兵劫掠城外，宜高阜伏矢以射之，必有獲也。</p><p>○　問營商：運貨出外，防有盜劫，宜嚴備禦，非特無失，且可以獲盜糧也，故曰“無不利”。</p><p>○　問功名：爻稱公，必已貴顯也，當立功於外。</p><p>○　問家宅：墉牆宜高，可備外竊。</p><p>○　問婚姻：《詩》雲“弋鳧與雁”，有射之象，吉。</p><p>○　問訟事：悖逆自解，利。</p><p>○　問六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>鎌倉圓覺寺住僧今北洪川和尚，博曉釋典，當今之高僧也。予一日遊鎌倉，欲訪和尚，意予所談在《易》理，和尚所說在禪味，不知禪之三昧，與易之六爻，其旨果相符合否耶？試為一佔，筮得《解》之《未濟》。</p><p>斷曰，佛法以解脫為宗旨，取解脫煩惱之義也。今得《解》上爻，不言《解》而言射，是用佛法，攝伏外魔，內性既定，外魔自消，與《解》所云之“三狐”為內魔，上之“隼”為外魔，其旨相同。知今日和尚，對餘所談，大旨如斯，予乃就卦義，書道歌一首，懷之以訪和尚。和尚延予入禪堂，茗談移晷，佛法《易》理，各極其妙，遂出道歌示之，一笑而別。</p><p>一日橫濱商人左右田金作氏來訪，請佔利根運河株式高低。筮得《解》之《未濟》。</p><p>斷曰：《解》者，動而免險之卦。方今賣卻株式，得此難得之利益，以免後日之災，故曰“無不利”。恰如見隼集於高墉之上，一矢射之，以去後患，若遷延過時，及至《損》卦，必有損而無利也。氏從此言，一次賣之，即得利益；後因獲利，而復買之，致招損失雲。</p><p>明治三十一年，佔伊藤內閣氣運，筮得《解》之《未濟》。</p><p>斷曰：爻辭曰“公”，適合內閣之稱也；內閣居高位，故曰“高墉”。“隼”，指政黨首領而言。政黨首領，身處位外，飛揚跋扈，每與政府為難，如隼之悍鷙善掠，殘害善類，六五之君，命公乘高，射而獲之。不曰殲而曰獲，以隼本有用之材，素有功勞，故期獲而用之，以收其效，故曰“獲之，無不利”也。《象傳》曰“解悖”，是謂《解》去悖逆之心，以冀歸順也。內閣躬膺總理，既修文德，又具武功，靖內難，戢外侮，固公之所優為，《解》之上而難解，正公今之時也。然《解》難為解，解位亦為解，尤公所宜慎審。遂呈此佔於內閣，後內閣推薦大隈板垣兩伯，問餘以占斷當否？餘曰：執一隼，又欲獲一隼，但恐所執之隼，振羽欲翔，放手遂不得復執；兩隼相軋，而不能相容。公乃遂辭內閣，亦合《解》卦之義也。</p>',116)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
